using System.Security.Claims; using Mentorly.Application.DTOs; using Mentorly.Application.Services; using Mentorly.Infrastructure.Identity; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc;
namespace Mentorly.Api.Controllers;
[ApiController][Route("api")]
public class QuizzesController(IQuizService quizService):ControllerBase
{ [Authorize(Policy=MentorlyPolicies.Student)][HttpGet("activities/{activityId:guid}/quiz")] public async Task<ActionResult<IEnumerable<QuizQuestionDto>>> GetAsync(Guid activityId,CancellationToken c=default)=>Ok(await quizService.GetQuestionsAsync(activityId,c)); [Authorize(Policy=MentorlyPolicies.Admin)][HttpPost("activities/{activityId:guid}/quiz/questions")] public async Task<ActionResult<QuizQuestionDto>> CreateAsync(Guid activityId,CreateQuizQuestionDto dto,CancellationToken c=default){var q=await quizService.CreateQuestionAsync(activityId,dto,c);return q is null?NotFound():CreatedAtAction(nameof(GetAsync),new{activityId},q);}[Authorize(Policy=MentorlyPolicies.Student)][HttpPost("enrollments/{enrollmentId:guid}/activities/{activityId:guid}/quiz-attempts")] public async Task<ActionResult<QuizAttemptDto>> SubmitAsync(Guid enrollmentId,Guid activityId,SubmitQuizAttemptDto dto,CancellationToken c=default){if(!Guid.TryParse(User.FindFirstValue(MentorlyClaimTypes.StudentId),out var studentId))return Unauthorized();try{var attempt=await quizService.SubmitAsync(enrollmentId,studentId,activityId,dto,c);return attempt is null?NotFound():Ok(attempt);}catch(InvalidOperationException e){return Conflict(new{message=e.Message});}} }
